  r := [];
  var i: int := 1;
  while i <= m
    invariant len(r) == i - 1
    invariant forall k in [0, i - 1) . r[k] == n * (k + 1)
    invariant i >= 1 and i <= m + 1
    decreases m - i + 1
  {
    r := r + [n * i];
    i := i + 1;
  }
}
