task findPoisonedDuration(timeSeries: seq, duration: int) returns (r: int)
  requires forall i in [0, len(timeSeries)) . timeSeries[i] >= 0
  requires duration >= 0
  ensures r >= 0
  ensures r == sum_overlaps(timeSeries, duration)
spec fun sum_overlaps(timeSeries: seq, duration: int): int
  decreases len(timeSeries)
= if len(timeSeries) == 0 then 0 else
  if len(timeSeries) == 1 then duration else
  let start = timeSeries[0]
      end = start + duration
      next_start = timeSeries[1]
      overlap = if next_start < end then end - next_start else 0
      remaining = sum_overlaps(timeSeries[1..len(timeSeries)], duration)
  in
    if next_start <= end then
      duration - overlap + remaining
    else
      duration + remaining
{
  if len(timeSeries) <= 1 {
    r := len(timeSeries) * duration;
  } else {
    r := 0;
    var i: int := 0;
    while i < len(timeSeries) - 1
      invariant r >= 0
      invariant i >= 0 and i < len(timeSeries) - 1
      decreases len(timeSeries) - 1 - i
    {
      var current_start: int := timeSeries[i];
      var current_end: int := current_start + duration;
      var next_start: int := timeSeries[i + 1];

      if next_start < current_end {
        // Overlapping intervals
        var overlap: int := current_end - next_start;
        r := r + duration - overlap;
      } else {
        // Non-overlapping intervals
        r := r + duration;
      }
      i := i + 1;
    }

    // Add the last duration
    r := r + duration;
  }
}
