task getSum(a: int, b: int) returns (r: int)
  ensures r == a + b
{
  r := 0;
  var carry: int := 0;
  var i: int := 0;
  var temp_a: int := a;
  var temp_b: int := b;

  while i < 32
    invariant i >= 0 and i <= 32
    decreases 32 - i
  {
    var bit_a: int := temp_a & 1;
    var bit_b: int := temp_b & 1;
    var sum_bits: int := bit_a + bit_b + carry;

    if sum_bits == 0 {
      r := r | (0 << i);
      carry := 0;
    } else if sum_bits == 1 {
      r := r | (1 << i);
      carry := 0;
    } else if sum_bits == 2 {
      r := r | (0 << i);
      carry := 1;
    } else {
      r := r | (1 << i);
      carry := 1;
    }

    temp_a := temp_a >> 1;
    temp_b := temp_b >> 1;
    i := i + 1;
  }
}
