  var valid_dates: seq := [];
  var i: int := 0;
  while i < len(nums)
    invariant 0 <= i
    invariant i <= len(nums)
    decreases len(nums) - i
  {
    var j: int := 0;
    while j < len(nums)
      invariant 0 <= j
      invariant j <= len(nums)
      decreases len(nums) - j
    {
      if i != j {
        var k: int := 0;
        while k < len(nums)
          invariant 0 <= k
          invariant k <= len(nums)
          decreases len(nums) - k
