task balanced_num(n: int) returns (r: seq)
  ensures r == "Balanced" or r == "Not Balanced"
{
  var s: seq := tostr(n);
  var len_s: int := len(s);
  var left_sum: int := 0;
  var right_sum: int := 0;

  if len_s % 2 == 1 {
    // odd number of digits - one middle digit
    var mid: int := len_s / 2;
    var i: int := 0;
    while i < mid
      invariant 0 <= i
      invariant i <= mid
      invariant left_sum == sum_slice(s, 0, i)
      decreases mid - i
    {
      left_sum := left_sum + s[i];
      i := i + 1;
    }

    i := mid + 1;
    while i < len_s
      invariant i >= mid + 1
      invariant i <= len_s
      invariant right_sum == sum_slice(s, i, len_s)
      decreases len_s - i
    {
      right_sum := right_sum + s[i];
      i := i + 1;
    }
  } else {
    // even number of digits - two middle digits
    var mid: int := len_s / 2;
    var i: int := 0;
    while i < mid - 1
      invariant 0 <= i
      invariant i <= mid - 1
      invariant left_sum == sum_slice(s, 0, i + 1)
      decreases mid - 1 - i
    {
      left_sum := left_sum + s[i];
      i := i + 1;
    }

    i := mid;
    while i < len_s
      invariant i >= mid
      invariant i <= len_s
      invariant right_sum == sum_slice(s, i, len_s)
      decreases len_s - i
    {
      right_sum := right_sum + s[i];
      i := i + 1;
    }
  }

  if left_sum == right_sum {
    r := "Balanced";
  } else {
    r := "Not Balanced";
  }
}

spec fun sum_slice(s: seq, start: int, end: int): int
  decreases end - start
= if start >= end then 0 else s[start] + sum_slice(s, start + 1, end)
